<style lang="scss" scoped src="./donor-information-block.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../../components/icon/icon";
import Button from "../../components/button/button";
import {
  ButtonSize,
  ButtonMode,
} from "../../components/button/button.constants";
import { IconShape } from "../../components/icon/icon.constants";

@Component({
  components: {
    Button,
    Icon,
  },
})
export default class DonorInformationBlock extends Vue {
  @Prop({
    type: String,
    default: "",
  })
  name;

  @Prop({
    type: String,
    default: "",
  })
  email;

  /**
    {
      street: String;
      city: String;
      state: String;
      zip: String;
    }
   */
  @Prop({
    type: Object,
    default: () => {},
  })
  address;

  @Prop({
    type: String,
    default: "",
  })
  phone;

  IconShape = IconShape;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;

  get address_line1() {
    return `${this.address.street}.`;
  }

  get address_line2() {
    return `${this.address.city}, ${this.address.state} ${this.address.zip}`;
  }

  handleContactDonor() {
    /**
     * Event when users click contact donor button
     *
     * @event contact
     */
    this.$emit("contact");
  }

  handleClickField(field, value) {
    return () => {
      /**
       * Emits when the user clicks a field of data. Provides the field name and
       * the value associated with it.
       *
       * @event clickField
       */
      this.$emit("clickField", field, value);
    };
  }
}
</script>

<template>
  <div class="DonorInformationBlock">
    <div class="DonorInformationBlock__Header">
      <div class="DonorInformationBlock__Title">
        {{ "Donor Information" }}
      </div>
      <Button
        :mode="ButtonMode.GMS_SUBTLE"
        :size="ButtonSize.SMALL"
        label="Contact Donor"
        @click="handleContactDonor"
      />
    </div>
    <div
      class="DonorInformationBlock__Unit"
      @click="handleClickField('name', name)"
    >
      <h1>{{ "Name" }}</h1>
      <h3 :style="{ cursor: 'pointer' }">{{ name }}</h3>
    </div>
    <div
      class="DonorInformationBlock__Unit"
      @click="handleClickField('email', email)"
    >
      <h1>{{ "Email" }}</h1>
      <h2>{{ email }}</h2>
    </div>
    <div
      class="DonorInformationBlock__AddressUnit"
      @click="handleClickField('address', address)"
    >
      <h1>{{ "Address" }}</h1>
      <div class="DonorInformationBlock__Address">
        <h2>{{ address_line1 }}</h2>
        <h2>{{ address_line2 }}</h2>
      </div>
    </div>
    <div
      class="DonorInformationBlock__Unit"
      @click="handleClickField('phone', phone)"
    >
      <h1>{{ "Phone" }}</h1>
      <h2>{{ phone }}</h2>
    </div>
  </div>
</template>
